SELECT
	,
	b.alarm_name,
	c.template_name
FROM swm_alarm_light_config a


	a.status = #{STATUS_NORMAL}

		AND a.light_id = #{lightId}


		AND a.alarm_config_id = #{alarmConfigId}




		ORDER BY ${page.orderBy}


		ORDER BY a.create_date ASC

SELECT , b.alarm_name, c.template_name FROM swm_alarm_light_config a
a.status = #{STATUS_NORMAL}
ORDER BY ${page.orderBy}
ORDER BY a.create_date ASC
